#!/usr/bin/env python3
"""Write datum_dump.inc: one block per ORE market datum class that prints
every inspector the class declares.

The harness has to report what ORE's own parser put in each field of a datum.
ORE's boost serializers cannot do it: they are instantiated for binary archives
only, write no field names, and skip fields (CdsQuote omits its doc clause and
running spread). The inspectors are the complete, named view, so this script
reads them from marketdatum.hpp and the harness calls them.

Usage: generate_dump.py <ORE source dir> <output file>
"""

import re
import sys
from pathlib import Path

CLASS_RE = re.compile(r"^class (\w+)\s*:\s*public (\w+)")
# An inline inspector: a return type, a name, no parameters, and its body on the
# same line. ORE declares most inspectors const and a few, the inflation swaps
# among them, not.
GETTER_RE = re.compile(
    r"^\s*(?:virtual\s+)?(?P<type>(?:const\s+)?[\w:][\w:<>,\s]*?)\s*&?\s+(?P<name>\w+)\(\)"
    r"\s*(?:const\s*)?(?:override\s*)?\{")
SKIPPED = {"clone", "quote", "asofDate"}


def classes(header: str):
    """(class, base, [getter names]) for every class deriving from a datum."""
    result = []
    current = None
    depth = 0
    for line in header.splitlines():
        if current is None:
            m = CLASS_RE.match(line)
            if m:
                current = (m.group(1), m.group(2), [])
                depth = 0
                started = False
            else:
                continue
        depth += line.count("{") - line.count("}")
        if "{" in line:
            started = True
        g = GETTER_RE.match(line)
        if (g and g.group("name") not in SKIPPED and g.group("name") != current[0]
                and g.group("name") not in current[2]):
            current[2].append(g.group("name"))
        if started and depth <= 0:
            result.append(current)
            current = None
    return result


def main():
    source, output = Path(sys.argv[1]), Path(sys.argv[2])
    header = (source / "OREData/ored/marketdata/marketdatum.hpp").read_text()
    found = classes(header)
    datum_classes = {"MarketDatum"}
    for name, base, _ in found:
        if base in datum_classes or base.endswith("Quote") or base == "MarketDatum":
            datum_classes.add(name)

    out = [
        "// Generated by generate_dump.py from OREData/ored/marketdata/marketdatum.hpp.",
        "// Regenerate rather than edit.",
        "",
    ]
    for name, base, getters in found:
        if name not in datum_classes or not getters:
            continue
        out.append(f"if (const auto p = QuantLib::ext::dynamic_pointer_cast<ore::data::{name}>(d)) {{")
        for g in getters:
            out.append(f'    fields.emplace_back("{g}", fmt(p->{g}()));')
        out.append("}")
    output.write_text("\n".join(out) + "\n")
    print(f"{len(datum_classes) - 1} datum classes, written to {output}")


if __name__ == "__main__":
    main()
